    function populateModels(catKey) {
        modelSelect.innerHTML = '';
        const models = WT3D_DATABASE[catKey] || [];
        models.forEach((m, idx) => {
            const opt = document.createElement('option');
            opt.value = idx;
            opt.textContent = `${idx + 1}. ${m.name}`;
            modelSelect.appendChild(opt);
        });
        updateModelInfo();
    }

    function updateModelInfo() {
        const catKey = folderSelect.value;
        const idx = parseInt(modelSelect.value) || 0;
        const m = WT3D_DATABASE[catKey] ? WT3D_DATABASE[catKey][idx] : null;
        if (m) {
            priceTag.textContent = `$${m.cgtrader_price} (Niêm yết) → Sale 50%: $${m.cgtrader_sale_price}`;
            let fp = (m.folder_path || '').trim();
            if (fp.endsWith('\\')) fp = fp.slice(0, -1);
            const normBase = fp.endsWith('06_Renders_and_Media') ? fp : `${fp}\\06_Renders_and_Media`;
            curPkgPath = `${normBase}\\01_Marketplace_Upload_Package`;
            curImgPath = `${normBase}\\02_Images_4K_Previews`;
            curVidPath = `${normBase}\\04_Finished_Videos`;
        }
    }

    async function openFolderInExplorer(path, label) {
        if (!path) {
            statusText.textContent = 'Chưa có đường dẫn. Chọn model trước!';
            statusText.style.color = '#f87171';
            return;
        }
        try { await navigator.clipboard.writeText(path); } catch (e) {}

        statusText.textContent = '📂 Đang mở Explorer: ' + label + '...';
        statusText.style.color = '#38bdf8';

        chrome.runtime.sendMessage({ action: 'openFolderInExplorer', path: path }, (res) => {
            if (res && res.success && res.via === 'bridge') {
                statusText.textContent = '📂 Đã mở Explorer: ' + label;
                statusText.style.color = '#10b981';
            } else if (res && res.success) {
                statusText.textContent = '🌐 Đã mở Tab: ' + label;
                statusText.style.color = '#38bdf8';
            } else {
                statusText.textContent = '📋 Đã copy đường dẫn: ' + label;
                statusText.style.color = '#facc15';
            }
        });
    }

